  'report.title': 'Berichtseinstellungen', 'report.subtitle': 'Private lokale Diagnose und Einwilligung',
  'report.automatic': 'Automatische Diagnoseberichte',
  'report.destination': 'Diagnoseberichte werden an https://gamja.top/api/gamja-bot/reports gesendet, wenn der geprüfte Dienst verfügbar ist. In diesem Build ist die Übermittlung nicht verfügbar, wenn der Empfänger nicht konfiguriert wurde.',
  'report.contents': 'Berichte enthalten App- und Buildversion, Betriebssystem und Architektur, Zeit, Komponente, Phase, festen Fehlercode, Anzahl der Vorkommnisse und bis zu 16 feste Übergänge. Ein Fehler mit bereinigter Diagnose enthält außerdem eine Korrelations-ID, einen festen Grund und eine feste Ausnahmeklasse, app-relative Stapelrahmen, begrenzte Kontext-IDs, HTTP-Status und eine geprüfte Anbieter-Anfrage-ID. Sie enthalten weder Chats noch Agentenanweisungen, Anbietertext, Schlüssel, URLs, Home-Pfade, Prozessausgaben, Zwischenablage, Browserinhalte, Screenshots, Rohprotokolle oder Anfrage- und Antworttexte. Eine optionale manuelle Beschreibung wird separat behandelt und vor der Übermittlung angezeigt.',
  'report.retention': 'Lokale, nicht gesendete Berichte verfallen nach 7 Tagen. Angenommene Berichte werden beim Empfänger 30 Tage lang aufbewahrt. Vor der Aktivierung der Liveübermittlung sind ein veröffentlichter Datenschutzhinweis und ein Zugriffsverfahren für Betreiber erforderlich.',
  'report.consent': 'Diese Auswahl gilt während dieser App-Sitzung für diese Installation in Ihrem Betriebssystem-Benutzerprofil. Sie umfasst nur neue Fehler nach der Aktivierung. Nach einem App-Neustart ist die automatische Berichterstattung ausgeschaltet; aktivieren Sie sie für diese Sitzung erneut. Das Ausschalten beendet weitere automatische Versuche und entfernt nicht gesendete automatische Berichte. Ein bereits empfangener Bericht kann mit diesem Schalter nicht zurückgerufen werden.',
  'report.autoSend': 'Diagnosefehler automatisch senden', 'report.loading': 'Lokale Berichtseinstellungen werden geladen…',
  'report.unavailable': 'Übermittlung nicht verfügbar. Die automatische Teilnahme ist verfügbar, sobald der geprüfte Empfänger konfiguriert ist.',
  'report.localCount': { one: '{count} lokaler Bericht', other: '{count} lokale Berichte' },
  'report.entryCount': { one: '{count} Diagnoseeintrag', other: '{count} Diagnoseeinträge' },
