  'problem.export': 'Bericht exportieren', 'problem.delete': 'Bericht löschen', 'problem.title': 'Problem melden',
  'problem.destination': 'Ziel: {destination}.',
  'problem.privacy': 'Nur die in der vollständigen Berichtsvorschau angezeigten Felder werden gesendet. Ausgewählte Fehler können eine Korrelations-ID, einen festen Grund und eine feste Ausnahmeklasse, app-relative Stapelrahmen, begrenzte Kontext-IDs, HTTP-Status und eine geprüfte Anbieter-Anfrage-ID enthalten. Chats, Schlüssel, Screenshots, Rohprotokolle, lokale Pfade, Anfrage- oder Antworttexte und Dateien werden nicht erfasst. Von Ihnen eingegebener Text kann personenbezogene Daten enthalten.',
