  "chat.failureReference.copied": "Fehlerreferenz kopiert.",
  "chat.failureReference.help": "Enthält nur Raum-/Ereignis-IDs, formatgeprüfte Codes/Referenzen und eine Position in dieser App. Kein Gesprächstext, keine rohen Fehlermeldungen oder Zugangsdaten. Teile nur für den Bericht Nötiges. Der Link gewährt keinen Zugriff und belegt keinen aktuellen Fehler.",

  "chat.failure.invalidProviderResponse": "Die Anbieterantwort konnte bei diesem aufgezeichneten Versuch nicht verarbeitet werden. Prüfe den erreichten Arbeitsstand und die aktuelle Verbindung/das Modell. Es wird nichts automatisch neu gestartet.",
  "chat.failure.unsupportedOption": "Verbindung/Modell unterstützten bei diesem aufgezeichneten Versuch eine angeforderte Option nicht. Prüfe aktuell unterstützte Optionen und Einstellungen; wähle Änderungen ausdrücklich.",
  "chat.failure.secretStoreUnavailable": "Der Zugriff auf gespeicherte Zugangsdaten war bei diesem aufgezeichneten Versuch nicht verfügbar. Das beweist keinen fehlenden oder ungültigen Schlüssel. Behalte vorhandene Werte und prüfe zuerst den aktuellen Authentifizierungsstatus.",
  "recovery.viewFailure": "Ursprünglichen Fehler im Gespräch öffnen",
  "recovery.continueEffect": "Fortsetzen sendet eine neue Nachricht und kann Agent-Arbeit und Anbieter-Nutzung starten. Alte Werkzeuge werden nicht automatisch wiederholt.",
  "recovery.continueUnknown": "Keine Antwort erhalten. Nachricht oder Arbeit könnte bereits gestartet sein. Prüfen Sie Gespräch und aktuelle Arbeit.",
