  "recovery.continueAcceptedHelp": "Anfrage angenommen. Agent-Erfolg ist separat; hier wird nicht erneut gesendet.",
  "recovery.navigationState": "Der Anfragestatus bleibt beim Verlassen und Zurückkehren in dieser Anmeldung erhalten. Kein Wiederherstellen nach App-Neustart oder Abmeldung und keine serverseitige Deduplizierung.",
  "recovery.requestHistory": "Fortsetzungsanfragen",
  "recovery.historyUnknown": "Antwort unbekannt",
  "recovery.openAccepted": "Angenommene Nachricht ansehen",
  "recovery.historyHelp": "Anfragen aus dieser Ansicht in dieser Anmeldung. Annahme ist kein Ausführungserfolg; spätere Annahmen klären frühere unbekannte Antworten nicht. Öffnen sendet nicht erneut.",
  "results.textFind.memoryHelp": "Suchtext und Groß-/Kleinschreibung bleiben je Raum/Ergebnis/Version in dieser Anmeldung erhalten, nicht nach App-Neustart oder Abmeldung. Text und Trefferposition werden nicht gespeichert; kein automatisches Öffnen oder Scrollen. Ältere Werte können aus dem Ansichtsspeicher verdrängt werden.",
  "results.textFind.resetMemory": "Sucheinstellungen dieser Version löschen",
  "results.fileSave.title": "Inhalt v{version} als Datei",
  "results.fileSave.action": "Original v{version} als .md speichern",
  "results.fileSave.panelTitle": "Speicherort für Ergebnisinhalt",
  "results.fileSave.help": "Speichert nur den empfangenen Originalinhalt dieser Version als UTF-8 Markdown, ohne Darstellungskonvertierung, Gespräch, Bewertungen oder andere Versionen. Links werden nur als URL gespeichert, nicht abgerufen. Ziel und Ersetzen wählen Sie.",
  "results.fileSave.limit": "Bis 2 MiB, kein leerer Inhalt oder NUL. Versions-/Owner-/Ansichtswechsel oder Schließen während der Auswahl bricht vor dem Schreiben ab. Bereits begonnenes Schreiben wird nicht abgebrochen. Verlauf nur in der Anmeldung; Dateien bleiben nach Abmeldung.",
  "results.fileSave.saved": "Original dieser Ergebnisversion als Markdown gespeichert.",
  "results.fileSave.size": "Kein leerer Inhalt oder NUL; UTF-8-Limit 2 MiB. Keine Kürzung. Nutzen Sie Kopieren oder manuelle Auswahl.",
  "results.fileSave.historyScope": "Speicherversuche dieser Anmeldung, dieses Raums, Ergebnisses und dieser Version. Kein erneutes Lesen oder Speichern. Kein Verlauf nach Abmeldung/App-Ende; Filtern und Zuklappen löschen keine Ergebnisse.",
  "results.comparison.jumpTitle": "Vergleich nach Nummer wählen",
  "results.comparison.jumpLabel": "Vergleichsversion",
  "results.comparison.jumpHelp": "Zuletzt empfangen: v{latest}. Geben Sie 1–{latest} außer v{selected} ein, z. B. v17. Liest die Version direkt ohne ganze Liste und ändert nicht die ausgewählte Ergebnisversion. Vollbreite Ziffern und ｖ sind ebenfalls möglich (z. B. ｖ１７).",
  "results.comparison.jumpWaiting": "Nach Empfang der neuesten Versionsnummer verfügbar.",
