  "results.closeDetail": "Detail schließen und Liste ansehen",
  "results.closeDetailHelp": "Löscht nur die Detailauswahl. Entwürfe und serverseitige Speicher-/Befehlsbelege bleiben; bereits gesendete Serveranfragen werden nicht abgebrochen. Zur Liste bewegt nur die Ansicht und hält das Detail offen.",
  "results.readingNavigation.title": "In diesem Ergebnis navigieren",
